CREATE TABLE iso16757_document (
 id INTEGER PRIMARY KEY, catalogue_id TEXT NOT NULL, metadata_names_id INTEGER NOT NULL REFERENCES iso16757_names(id), revision TEXT NOT NULL, status TEXT NOT NULL, valid_from TEXT, valid_to TEXT, edition_profile TEXT NOT NULL, manufacturer_id TEXT NOT NULL, manufacturer_names_id INTEGER NOT NULL REFERENCES iso16757_names(id), catalogue_dictionary_id TEXT NOT NULL, catalogue_dictionary_version TEXT NOT NULL, dictionary_id TEXT NOT NULL, dictionary_version TEXT NOT NULL, selection_class_id TEXT NOT NULL, selection_series_id TEXT, part_number_kind TEXT NOT NULL, literal_value TEXT, output_column TEXT, function_id TEXT, script_source TEXT, max_steps INTEGER NOT NULL, max_recursion INTEGER NOT NULL, timeout_ms_high INTEGER NOT NULL, timeout_ms_low INTEGER NOT NULL, exchange_process TEXT NOT NULL
);
CREATE TABLE iso16757_names (id INTEGER PRIMARY KEY, preferred_locale TEXT NOT NULL, preferred_text TEXT NOT NULL, short_name TEXT);
CREATE TABLE iso16757_name_alternative (id INTEGER PRIMARY KEY, names_id INTEGER NOT NULL REFERENCES iso16757_names(id), ordinal INTEGER NOT NULL, locale TEXT NOT NULL, text TEXT NOT NULL);
CREATE TABLE iso16757_unit (id INTEGER PRIMARY KEY, symbol TEXT NOT NULL, length INTEGER NOT NULL, mass INTEGER NOT NULL, time INTEGER NOT NULL, temperature INTEGER NOT NULL, si_factor REAL, si_factor_ieee754_bits INTEGER, si_factor_ieee754_class TEXT);
CREATE TABLE iso16757_catalogue_value (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, boolean_value INTEGER, integer_value INTEGER, decimal_value REAL, text_value TEXT, list_id TEXT, unit_id INTEGER REFERENCES iso16757_unit(id), range_min REAL, range_max REAL, null_state TEXT, target_id TEXT, decimal_value_ieee754_bits INTEGER, decimal_value_ieee754_class TEXT, range_min_ieee754_bits INTEGER, range_min_ieee754_class TEXT, range_max_ieee754_bits INTEGER, range_max_ieee754_class TEXT);
CREATE TABLE iso16757_value_element (id INTEGER PRIMARY KEY, parent_value_id INTEGER NOT NULL REFERENCES iso16757_catalogue_value(id), ordinal INTEGER NOT NULL, value_id INTEGER NOT NULL REFERENCES iso16757_catalogue_value(id));
CREATE TABLE iso16757_product_group (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, names_id INTEGER NOT NULL REFERENCES iso16757_names(id), dictionary_subject_id TEXT);
CREATE TABLE iso16757_product_class (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, group_id TEXT NOT NULL, parent_id TEXT, names_id INTEGER NOT NULL REFERENCES iso16757_names(id));
CREATE TABLE iso16757_class_required_property (id INTEGER PRIMARY KEY, class_id INTEGER NOT NULL REFERENCES iso16757_product_class(id), ordinal INTEGER NOT NULL, property_id TEXT NOT NULL);
CREATE TABLE iso16757_class_optional_property (id INTEGER PRIMARY KEY, class_id INTEGER NOT NULL REFERENCES iso16757_product_class(id), ordinal INTEGER NOT NULL, property_id TEXT NOT NULL);
CREATE TABLE iso16757_product_series (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, class_id TEXT NOT NULL, names_id INTEGER NOT NULL REFERENCES iso16757_names(id), geometry_id TEXT);
CREATE TABLE iso16757_series_property (id INTEGER PRIMARY KEY, series_id INTEGER NOT NULL REFERENCES iso16757_product_series(id), ordinal INTEGER NOT NULL, property_key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES iso16757_catalogue_value(id));
CREATE TABLE iso16757_product (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, series_id TEXT NOT NULL, names_id INTEGER NOT NULL REFERENCES iso16757_names(id));
CREATE TABLE iso16757_parameter_domain (id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES iso16757_product(id), ordinal INTEGER NOT NULL, parameter_id TEXT NOT NULL, default_value_id INTEGER REFERENCES iso16757_catalogue_value(id));
CREATE TABLE iso16757_domain_allowed_value (id INTEGER PRIMARY KEY, domain_id INTEGER NOT NULL REFERENCES iso16757_parameter_domain(id), ordinal INTEGER NOT NULL, value_id INTEGER NOT NULL REFERENCES iso16757_catalogue_value(id));
CREATE TABLE iso16757_product_variant (id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES iso16757_product(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, article_number TEXT, geometry_id TEXT);
CREATE TABLE iso16757_variant_parameter (id INTEGER PRIMARY KEY, variant_id INTEGER NOT NULL REFERENCES iso16757_product_variant(id), ordinal INTEGER NOT NULL, parameter_key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES iso16757_catalogue_value(id));
CREATE TABLE iso16757_property_value (id INTEGER PRIMARY KEY, definition_id TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES iso16757_catalogue_value(id), function_id TEXT);
CREATE TABLE iso16757_variant_property (id INTEGER PRIMARY KEY, variant_id INTEGER NOT NULL REFERENCES iso16757_product_variant(id), ordinal INTEGER NOT NULL, property_value_id INTEGER NOT NULL REFERENCES iso16757_property_value(id));
CREATE TABLE iso16757_product_static_property (id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES iso16757_product(id), ordinal INTEGER NOT NULL, property_value_id INTEGER NOT NULL REFERENCES iso16757_property_value(id));
CREATE TABLE iso16757_product_index (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, product_id TEXT NOT NULL, variant_id TEXT);
CREATE TABLE iso16757_index_tag (id INTEGER PRIMARY KEY, index_id INTEGER NOT NULL REFERENCES iso16757_product_index(id), ordinal INTEGER NOT NULL, tag TEXT NOT NULL);
CREATE TABLE iso16757_property_definition (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, names_id INTEGER NOT NULL REFERENCES iso16757_names(id), data_type TEXT NOT NULL, unit_id INTEGER REFERENCES iso16757_unit(id), cardinality_min INTEGER NOT NULL, cardinality_max INTEGER, property_kind TEXT NOT NULL, dictionary_property_id TEXT);
CREATE TABLE iso16757_accessory_group (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, product_key TEXT NOT NULL);
CREATE TABLE iso16757_accessory (id INTEGER PRIMARY KEY, group_id INTEGER NOT NULL REFERENCES iso16757_accessory_group(id), ordinal INTEGER NOT NULL, accessory_product_id TEXT NOT NULL, required INTEGER NOT NULL, quantity_min INTEGER NOT NULL, quantity_max INTEGER, compatibility_condition TEXT);
CREATE TABLE iso16757_composition_group (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, product_key TEXT NOT NULL);
CREATE TABLE iso16757_composition (id INTEGER PRIMARY KEY, group_id INTEGER NOT NULL REFERENCES iso16757_composition_group(id), ordinal INTEGER NOT NULL, component_product_id TEXT NOT NULL, quantity INTEGER NOT NULL);
CREATE TABLE iso16757_descriptive_object (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, media_type TEXT NOT NULL, uri TEXT NOT NULL, language TEXT, checksum TEXT);
CREATE TABLE iso16757_dictionary_subject (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), lane TEXT NOT NULL, ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, subject_kind TEXT NOT NULL, names_id INTEGER NOT NULL REFERENCES iso16757_names(id), definition_locale TEXT NOT NULL, definition_text TEXT NOT NULL, parent_id TEXT);
CREATE TABLE iso16757_dictionary_relationship (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, relationship_kind TEXT NOT NULL, source_id TEXT NOT NULL, target_id TEXT NOT NULL, cardinality_min INTEGER NOT NULL, cardinality_max INTEGER);
CREATE TABLE iso16757_dictionary_property (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, names_id INTEGER NOT NULL REFERENCES iso16757_names(id), property_kind TEXT NOT NULL, data_type TEXT NOT NULL, unit_id INTEGER REFERENCES iso16757_unit(id));
CREATE TABLE iso16757_property_subject (id INTEGER PRIMARY KEY, property_id INTEGER NOT NULL REFERENCES iso16757_dictionary_property(id), ordinal INTEGER NOT NULL, subject_id TEXT NOT NULL);
CREATE TABLE iso16757_value_constraint (id INTEGER PRIMARY KEY, property_id INTEGER NOT NULL REFERENCES iso16757_dictionary_property(id), ordinal INTEGER NOT NULL, minimum REAL, maximum REAL, minimum_ieee754_bits INTEGER, minimum_ieee754_class TEXT, maximum_ieee754_bits INTEGER, maximum_ieee754_class TEXT);
CREATE TABLE iso16757_constraint_allowed (id INTEGER PRIMARY KEY, constraint_id INTEGER NOT NULL REFERENCES iso16757_value_constraint(id), ordinal INTEGER NOT NULL, value TEXT NOT NULL);
CREATE TABLE iso16757_controlled_list (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL);
CREATE TABLE iso16757_controlled_value (id INTEGER PRIMARY KEY, list_id INTEGER NOT NULL REFERENCES iso16757_controlled_list(id), ordinal INTEGER NOT NULL, value TEXT NOT NULL);
CREATE TABLE iso16757_controlled_context (id INTEGER PRIMARY KEY, list_id INTEGER NOT NULL REFERENCES iso16757_controlled_list(id), ordinal INTEGER NOT NULL, subject_id TEXT NOT NULL);
CREATE TABLE iso16757_geometry_object (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, object_key TEXT NOT NULL, logical_id TEXT NOT NULL, shape_node_id INTEGER REFERENCES iso16757_geometry_node(id), symbolic_node_id INTEGER REFERENCES iso16757_geometry_node(id));
CREATE TABLE iso16757_geometry_node (id INTEGER PRIMARY KEY, node_kind TEXT NOT NULL, primitive_kind TEXT, boolean_operator TEXT, reference_geometry_id TEXT, translation_x REAL, translation_y REAL, translation_z REAL, rotation_x_deg REAL, rotation_y_deg REAL, rotation_z_deg REAL, translation_x_ieee754_bits INTEGER, translation_x_ieee754_class TEXT, translation_y_ieee754_bits INTEGER, translation_y_ieee754_class TEXT, translation_z_ieee754_bits INTEGER, translation_z_ieee754_class TEXT, rotation_x_deg_ieee754_bits INTEGER, rotation_x_deg_ieee754_class TEXT, rotation_y_deg_ieee754_bits INTEGER, rotation_y_deg_ieee754_class TEXT, rotation_z_deg_ieee754_bits INTEGER, rotation_z_deg_ieee754_class TEXT);
CREATE TABLE iso16757_geometry_child (id INTEGER PRIMARY KEY, parent_node_id INTEGER NOT NULL REFERENCES iso16757_geometry_node(id), ordinal INTEGER NOT NULL, child_node_id INTEGER NOT NULL REFERENCES iso16757_geometry_node(id));
CREATE TABLE iso16757_primitive_parameter (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES iso16757_geometry_node(id), ordinal INTEGER NOT NULL, parameter_key TEXT NOT NULL, value REAL, value_ieee754_bits INTEGER, value_ieee754_class TEXT);
CREATE TABLE iso16757_space (id INTEGER PRIMARY KEY, object_id INTEGER NOT NULL REFERENCES iso16757_geometry_object(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, space_kind TEXT NOT NULL, min_x REAL, min_y REAL, min_z REAL, max_x REAL, max_y REAL, max_z REAL, min_x_ieee754_bits INTEGER, min_x_ieee754_class TEXT, min_y_ieee754_bits INTEGER, min_y_ieee754_class TEXT, min_z_ieee754_bits INTEGER, min_z_ieee754_class TEXT, max_x_ieee754_bits INTEGER, max_x_ieee754_class TEXT, max_y_ieee754_bits INTEGER, max_y_ieee754_class TEXT, max_z_ieee754_bits INTEGER, max_z_ieee754_class TEXT);
CREATE TABLE iso16757_surface (id INTEGER PRIMARY KEY, object_id INTEGER NOT NULL REFERENCES iso16757_geometry_object(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, purpose TEXT NOT NULL, min_x REAL, min_y REAL, min_z REAL, max_x REAL, max_y REAL, max_z REAL, min_x_ieee754_bits INTEGER, min_x_ieee754_class TEXT, min_y_ieee754_bits INTEGER, min_y_ieee754_class TEXT, min_z_ieee754_bits INTEGER, min_z_ieee754_class TEXT, max_x_ieee754_bits INTEGER, max_x_ieee754_class TEXT, max_y_ieee754_bits INTEGER, max_y_ieee754_class TEXT, max_z_ieee754_bits INTEGER, max_z_ieee754_class TEXT);
CREATE TABLE iso16757_port (id INTEGER PRIMARY KEY, object_id INTEGER NOT NULL REFERENCES iso16757_geometry_object(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, medium TEXT NOT NULL, position_x REAL, position_y REAL, position_z REAL, direction_x REAL, direction_y REAL, direction_z REAL, port_type TEXT NOT NULL, position_x_ieee754_bits INTEGER, position_x_ieee754_class TEXT, position_y_ieee754_bits INTEGER, position_y_ieee754_class TEXT, position_z_ieee754_bits INTEGER, position_z_ieee754_class TEXT, direction_x_ieee754_bits INTEGER, direction_x_ieee754_class TEXT, direction_y_ieee754_bits INTEGER, direction_y_ieee754_class TEXT, direction_z_ieee754_bits INTEGER, direction_z_ieee754_class TEXT);
CREATE TABLE iso16757_geometry_binding (id INTEGER PRIMARY KEY, object_id INTEGER NOT NULL REFERENCES iso16757_geometry_object(id), ordinal INTEGER NOT NULL, parameter_key TEXT NOT NULL, property_id TEXT NOT NULL);
CREATE TABLE iso16757_primitive_kind (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL);
CREATE TABLE iso16757_primitive_kind_parameter (id INTEGER PRIMARY KEY, primitive_id INTEGER NOT NULL REFERENCES iso16757_primitive_kind(id), ordinal INTEGER NOT NULL, parameter TEXT NOT NULL);
CREATE TABLE iso16757_selection_constraint (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, logical_id TEXT NOT NULL, property_id TEXT NOT NULL, operator TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES iso16757_catalogue_value(id));
CREATE TABLE iso16757_part_number_row (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL);
CREATE TABLE iso16757_part_number_cell (id INTEGER PRIMARY KEY, row_id INTEGER NOT NULL REFERENCES iso16757_part_number_row(id), ordinal INTEGER NOT NULL, column_key TEXT NOT NULL, value TEXT NOT NULL);
CREATE TABLE iso16757_part_number_input (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, input_key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES iso16757_catalogue_value(id));
CREATE TABLE iso16757_extension_entry (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES iso16757_document(id), ordinal INTEGER NOT NULL, field_key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES iso16757_extension_value(id));
CREATE TABLE iso16757_extension_value (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, boolean_value INTEGER, integer_value INTEGER, unsigned_high INTEGER, unsigned_low INTEGER, float_value REAL, text_value TEXT, byte_value BLOB, float_value_ieee754_bits INTEGER, float_value_ieee754_class TEXT);
CREATE TABLE iso16757_extension_element (id INTEGER PRIMARY KEY, parent_value_id INTEGER NOT NULL REFERENCES iso16757_extension_value(id), ordinal INTEGER NOT NULL, value_id INTEGER NOT NULL REFERENCES iso16757_extension_value(id));
CREATE TABLE iso16757_extension_member (id INTEGER PRIMARY KEY, parent_value_id INTEGER NOT NULL REFERENCES iso16757_extension_value(id), ordinal INTEGER NOT NULL, member_key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES iso16757_extension_value(id));
